// Generated by node build.js.
function findPlayerAction(video, kind) {
  const pattern = kind === 'intro'
    ? /skip[\s_-]*(intro|opening)|pular[\s_-]*(abertura|intro)|saltar[\s_-]*(intro|introducci[oó]n)|ignorer[\s_-]*l.?intro/i
    : /next[\s_-]*episode|pr[oó]ximo[\s_-]*epis[oó]dio|epis[oó]dio[\s_-]*seguinte|siguiente[\s_-]*episodio/i;
  for (let root = video?.parentElement; root; root = root.parentElement) {
    const match = [...root.querySelectorAll('button, [role="button"], a')].find(el => {
      if (el.id?.startsWith('crunchyroll-pip-') || el.disabled
        || el.getAttribute('aria-disabled') === 'true' || el.closest('[hidden], [inert]')) return false;
      const label = [el.getAttribute('aria-label'), el.title,
        el.getAttribute('data-testid'), el.textContent].join(' ');
      const rect = el.getBoundingClientRect();
      const style = getComputedStyle(el);
      return pattern.test(label) && rect.width > 0 && rect.height > 0
        && style.display !== 'none' && style.visibility !== 'hidden';
    });
    if (match) return match;
  }
  return null;
}

function skipOpening(video) {
  const native = findPlayerAction(video, 'intro');
  if (native) { native.click(); return 'native'; }
  if (!video || video.readyState < 1 || !Number.isFinite(video.duration)
    || video.duration <= 0 || !Number.isFinite(video.currentTime)) return 'unavailable';
  const target = Math.min(video.currentTime + 90, video.duration);
  // Do not cross unavailable ranges (e.g. an unseekable live/ad segment).
  for (let i = 0; i < video.seekable.length; i++) {
    if (video.currentTime >= video.seekable.start(i) && video.currentTime <= video.seekable.end(i)) {
      video.currentTime = Math.min(target, video.seekable.end(i));
      return 'seek';
    }
  }
  return 'unavailable';
}

// Runs in the player's main world so existing media handlers can be restored.
(() => {
  if (!navigator.mediaSession) return;
  const session = navigator.mediaSession;
  const original = session.setActionHandler;
  const saved = new Map();
  let active = null;
  let observer = null;
  let timer = null;
  let nextAvailable = null;
  let lastNext = -Infinity;
  const controlled = new Set(['previoustrack', 'nexttrack']);
  const set = (action, handler) => original.call(session, action, handler);
  const previous = () => {
    if (active && document.pictureInPictureElement === active) skipOpening(active);
  };
  const next = () => {
    if (!active || document.pictureInPictureElement !== active || performance.now() - lastNext < 1500) return;
    const button = findPlayerAction(active, 'next');
    if (button) { lastNext = performance.now(); button.click(); }
    refresh();
  };
  function refresh() {
    if (!active) return;
    const available = Boolean(findPlayerAction(active, 'next'));
    if (available !== nextAvailable) {
      nextAvailable = available;
      set('nexttrack', available ? next : null);
    }
  }
  // Remember the player's registrations, including changes made while PiP is open.
  session.setActionHandler = function(action, handler) {
    if (this !== session || !controlled.has(action)) return original.call(this, action, handler);
    if (!active) {
      const result = original.call(this, action, handler);
      saved.set(action, handler);
      return result;
    }
    if (handler !== null && typeof handler !== 'function') return original.call(this, action, handler);
    saved.set(action, handler);
  };
  function stop() {
    if (!active) return;
    active = null;
    observer?.disconnect();
    clearTimeout(timer);
    nextAvailable = null;
    for (const action of controlled) set(action, saved.get(action) || null);
  }
  document.addEventListener('enterpictureinpicture', event => {
    stop();
    active = event.target;
    lastNext = -Infinity;
    set('previoustrack', previous);
    refresh();
    observer = new MutationObserver(() => {
      clearTimeout(timer);
      timer = setTimeout(refresh, 100);
    });
    observer.observe(document.documentElement, { childList: true, subtree: true,
      attributes: true, attributeFilter: ['disabled', 'aria-disabled', 'hidden', 'aria-label'] });
  }, true);
  document.addEventListener('leavepictureinpicture', event => {
    if (event.target === active) stop();
  }, true);
  window.addEventListener('pagehide', stop);
})();
